    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const messagesContainer = document.getElementById('messagesContainer');
            const messageInput = document.getElementById('messageInput');
            const sendBtn = document.getElementById('sendBtn');

            // Function to add a new message
            function addMessage(text, isCustomer) {
                const messageDiv = document.createElement('div');
                messageDiv.className = `message ${isCustomer ? 'customer' : 'agent'}`;

                const bubble = document.createElement('div');
                bubble.className = 'bubble';
                bubble.textContent = text;

                const time = document.createElement('div');
                time.className = 'time';

                // Get current time in Arabic format
                const now = new Date();
                const hours = now.getHours();
                const minutes = now.getMinutes().toString().padStart(2, '0');
                const period = hours >= 12 ? 'م' : 'ص';
                const displayHours = hours % 12 || 12;

                // Convert to Arabic-Indic digits
                const arabicHours = displayHours.toString().split('').map(digit => 
                    '٠١٢٣٤٥٦٧٨٩'[digit] || digit).join('');
                const arabicMinutes = minutes.split('').map(digit => 
                    '٠١٢٣٤٥٦٧٨٩'[digit] || digit).join('');

                time.textContent = `${arabicHours}:${arabicMinutes} ${period}`;

                messageDiv.appendChild(bubble);
                messageDiv.appendChild(time);

                messagesContainer.appendChild(messageDiv);
                messagesContainer.scrollTop = messagesContainer.scrollHeight;
            }

            // Send button click handler
            sendBtn.addEventListener('click', function() {
